"use client";

import { useEffect, useState } from "react";
import LifeTimeRandom from "./LifeTimeRandom";
import { isValidAccessCode } from "../lib/accessCode";

// No visible UI: opens the life-time-random page only when the URL carries a
// valid ?code= (the share links generated by LifeTimeRandom).
export default function SecretUnlock() {
  const [accessCode, setAccessCode] = useState<string | null>(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const codeParam = params.get("code");
    if (codeParam && isValidAccessCode(codeParam)) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setAccessCode(codeParam);
      window.history.replaceState(null, "", window.location.pathname);
    }
  }, []);

  if (!accessCode) return null;

  return <LifeTimeRandom accessCode={accessCode} onClose={() => setAccessCode(null)} />;
}
